'use strict';

// MODULES //

var tape = require( 'tape' );
var oneTo = require( '@stdlib/array/one-to' );
var zeros = require( '@stdlib/array/zeros' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );
var numel = require( '@stdlib/ndarray/base/numel' );
var shape2strides = require( '@stdlib/ndarray/base/shape2strides' );
var strides2offset = require( '@stdlib/ndarray/base/strides2offset' );
var ndarray = require( '@stdlib/ndarray/ctor' );
var blockSize = require( '@stdlib/ndarray/base/nullary-tiling-block-size' );
var whileEach = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof whileEach, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function invokes a callback function for each element in a 3-dimensional ndarray while a test condition is true (row-major, singleton dimensions)', function test( t ) {
	var expected;
	var values;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'float64';
	ord = 'row-major';
	sh = [ 4, 1, 1 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	values = [];
	x = ndarray( dt, oneTo( numel( sh ), dt ), sh, st, o, ord );

	whileEach( [ x ], predicate, fcn );

	expected = [ 1.0, 2.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v < 3.0;
	}

	function fcn( v ) {
		values.push( v );
	}
});

tape( 'the function invokes a callback function for each element in a 3-dimensional ndarray while a test condition is true (row-major, singleton dimensions, accessors)', function test( t ) {
	var expected;
	var values;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'complex128';
	ord = 'row-major';
	sh = [ 4, 1, 1 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	values = [];
	x = ndarray( dt, oneTo( numel( sh )*2, dt ), sh, st, o, ord );

	whileEach( [ x ], predicate, fcn );

	expected = [
		[ 1.0, 0.0 ],
		[ 2.0, 0.0 ]
	];
	t.deepEqual( values, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return real( v ) < 3.0;
	}

	function fcn( v ) {
		values.push( [ real( v ), imag( v ) ] );
	}
});

tape( 'the function invokes a callback function for each element in a 3-dimensional ndarray while a test condition is true (row-major, contiguous)', function test( t ) {
	var expected;
	var indices;
	var values;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'float64';
	ord = 'row-major';
	sh = [ 2, 1, 2 ];
	st = shape2strides( sh, ord );
	o = strides2offset( sh, st );

	values = [];
	indices = [];
	x = ndarray( dt, oneTo( numel( sh ), dt ), sh, st, o, ord );

	whileEach( [ x ], predicate, fcn );

	expected = [ 1.0, 2.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [
		[ 0, 0, 0 ],
		[ 0, 0, 1 ]
	];
	t.deepEqual( indices, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v < 3.0;
	}

	function fcn( v, idx ) {
		values.push( v );
		indices.push( idx );
	}
});

tape( 'the function invokes a callback function for each element in a 3-dimensional ndarray while a test condition is true (row-major, contiguous, negative strides)', function test( t ) {
	var expected;
	var indices;
	var values;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'float64';
	ord = 'row-major';
	sh = [ 2, 1, 2 ];
	st = [ -2, -2, -1 ];
	o = strides2offset( sh, st );

	values = [];
	indices = [];
	x = ndarray( dt, oneTo( numel( sh ), dt ), sh, st, o, ord );

	whileEach( [ x ], predicate, fcn );

	expected = [ 4.0, 3.0 ];
	t.deepEqual( values, expected, 'returns expected value' );

	expected = [
		[ 0, 0, 0 ],
		[ 0, 0, 1 ]
	];
	t.deepEqual( indices, expected, 'returns expected value' );

	t.end();

	function predicate( v ) {
		return v > 2.0;
	}

	function fcn( v, idx ) {
		values.push( v );
		indices.push( idx );
	}
});

