tape( 'the function invokes a callback function for each element in a 3-dimensional ndarray while a test condition is true (row-major, non-contiguous, large arrays)', function test( t ) {
	var expected;
	var bsize;
	var count;
	var ord;
	var sh;
	var st;
	var dt;
	var o;
	var x;

	dt = 'float64';
	ord = 'row-major';

	bsize = blockSize( dt );
	sh = [ bsize*2, 1, 2 ];
	st = [ -4, 4, 2 ];
	o = strides2offset( sh, st );

	count = 0;
	x = ndarray( dt, zeros( numel( sh )*2, dt ), sh, st, o, ord );

	whileEach( [ x ], predicate, fcn );

	expected = numel( sh );
	t.strictEqual( count, expected, 'returns expected value' );

	t.end();

	function predicate() {
		return true;
	}

	function fcn() {
		count += 1;
	}
});

